\label{thm:affine-interval-growth}
Assume that either \cref{setting:projective} or \cref{setting:kahler} holds.
Then for every maximal affine interval $[r,s]$ of $(\log\lambda_i(f))_i$, there is a constant $C_{f,\omega,r,s}>1$ such that for every $r\leq i\leq s$,
\begin{equation}\label{eq:affine-interval-growth}
\deg_{i,\omega}(f^n)\leq C_{f,\omega,r,s}\,n^{2(i-r)(s-i)}\lambda_i(f)^n,\qquad n\geq1.
\end{equation}
Consequently, there is a constant $C_{f,\omega}>1$ such that for every $0\leq i\leq d$,
\begin{equation}\label{eq:global-polynomial-growth}
\deg_{i,\omega}(f^n)\leq C_{f,\omega}\,n^{2i(d-i)}\lambda_i(f)^n,\qquad n\geq1.
\end{equation}
Together with \eqref{eq:standard-exponential-lower-bound}, this implies that for every $0\leq i\leq d$,
\begin{equation}\label{eq:global-log-growth}
\log\deg_{i,\omega}(f^n)=n\log\lambda_i(f)+O(\log n).
\end{equation}

\label{cor:no-intermediate-growth}
Assume that either \cref{setting:projective} or \cref{setting:kahler} holds.
Suppose that $f$ has zero entropy, i.e., $\lambda_1(f)=1$.\footnote{By log-concavity of the $\lambda_i(f)$, this is equivalent to $\lambda_i(f)=1$ for some or for all $1\le i\le d-1$.}
Then for every $1\le i\le d-1$,
\begin{equation}\label{eq:zero-entropy-polynomial-bound}
\deg_{i,\omega}(f^n)=O\bigl(n^{2i(d-i)}\bigr).
\end{equation}
Thus no degree sequence in either setting can be subexponential but superpolynomial.\footnote{A positive sequence $a_n$ is subexponential if $a_n=e^{o(n)}$, superpolynomial if $\log_na_n\to+\infty$.}

\label{thm:strict-break-asymptotics}
Assume that either \cref{setting:projective} or \cref{setting:kahler} holds, and let $1\leq i\leq d-1$ be a strict dynamical-degree break for $f$.
Then there is a constant $C_{f,\omega,i}>0$ such that for every $s_i(f)<\eta<\lambda_i(f)$, one has
\begin{equation}\label{eq:main-asymptotic}
\deg_{i,\omega}(f^n)=C_{f,\omega,i}\,\lambda_i(f)^n+O(\eta^n).
\end{equation}
Moreover, the leading constant is given by
\begin{equation}\label{eq:constant-C-exp-sum}
C_{f,\omega,i}=\operatorname{vol}_X(\omega)\exp\!\left(\sum_{m\geq1}m\log\frac{\deg_{i,\omega}(f^m)^2}{\deg_{i,\omega}(f^{m-1})\deg_{i,\omega}(f^{m+1})}\right),
\end{equation}
where the series converges absolutely with exponentially decaying tails.

\label{thm:degree-log-laplacian}
Assume that either \cref{setting:projective} or \cref{setting:kahler} holds.
For every $1\leq i\leq d-1$, there exists a constant $C'_{f,\omega,i}>0$ such that for every $n\geq1$,
\begin{equation}\label{eq:degree-log-laplacian}
\left|\log\frac{\deg_{i,\omega}(f^n)^2}{\deg_{i,\omega}(f^{n-1})\deg_{i,\omega}(f^{n+1})}\right|
\leq C'_{f,\omega,i}\, \frac{\sqrt{\deg_{i-1,\omega}(f^n)\deg_{i+1,\omega}(f^n)}}{\deg_{i,\omega}(f^n)}.
\end{equation}

\label{lemma:Ptolemy}
Let $V$ be a finite-dimensional real vector space and let $\mathscr{B}\colon V\times V\to\mathbf{R}$ be a symmetric bilinear form with positive index at most one.
If $v_1,\ldots,v_4\in V$ satisfy $\mathscr{B}(v_i,v_j)\geq0$ for all $1\le i,j\le 4$, then
\begin{equation}\label{eq:four-point-Ptolemy}
\Bigl|\sqrt{\mathscr{B}(v_1,v_2)\mathscr{B}(v_3,v_4)}-\sqrt{\mathscr{B}(v_1,v_4)\mathscr{B}(v_2,v_3)}\Bigr|\leq \sqrt{\mathscr{B}(v_1,v_3)\mathscr{B}(v_2,v_4)}.
\end{equation}

\label{prop:Ptolemy-estimate-unit-square}
With notation as above, suppose that for some $K\geq1$,
\begin{equation}\label{eq:comparison-A0A1-B0B1}
K^{-1}A_0\preceq_{\mathcal{P}}A_1\preceq_{\mathcal{P}}KA_0,\qquad
K^{-1}B_0\preceq_{\mathcal{P}}B_1\preceq_{\mathcal{P}}KB_0.
\end{equation}
Fix $1\leq i\leq d-1$ and assume that $\Phi_i>0$ on $[0,1]^2$.
Then for every $(s,t)\in[0,1]^2$,
\begin{equation}\label{eq:uniform-Ptolemy-unit-square}
\bigl|\partial_s\partial_t\log\Phi_i(s,t)\bigr|
\leq 2i(d-i)K^4\frac{\sqrt{\Phi_{i-1}(s,t)\Phi_{i+1}(s,t)}}{\Phi_i(s,t)}.
\end{equation}

\label{lemma:projective-two-time-shift}
With notation as above, for every $0\leq i\leq d$ and $0\leq m\leq\ell\leq N$,
\begin{equation}\label{eq:projective-two-time-shift}
\bigl(\omega_{m,N}^{d-i}\cdot \omega_{\ell,N}^i\bigr)_{Y_N}=\lambda_d(f)^m\deg_i(f^{\ell-m}).
\end{equation}

\label{lemma:projective-adjacent-comparison}
With notation as above, there is a constant $K_{f,\omega}\geq1$ such that for every $N\geq1$ and $0\leq m<N$,
\begin{equation}\label{eq:projective-adjacent-comparison}
K_{f,\omega}^{-1}\,\omega_{m,N}\preceq_{Y_N}\omega_{m+1,N}\preceq_{Y_N}K_{f,\omega}\,\omega_{m,N}.
\end{equation}

\label{prop:projective-log-laplacian}
Assume that \cref{setting:projective} holds.
For every $1\leq i\leq d-1$ and $n\geq1$,
\begin{equation}\label{eq:projective-log-laplacian}
\left|\log\frac{\deg_i(f^n)^2}{\deg_i(f^{n-1})\deg_i(f^{n+1})}\right|
\leq C'_{f,\omega,i}\,\frac{\sqrt{\deg_{i-1}(f^n)\deg_{i+1}(f^n)}}{\deg_i(f^n)},
\end{equation}
where $C'_{f,\omega,i}=2i(d-i)K_{f,\omega}^{2d+4}$ and $K_{f,\omega}$ is the constant in \cref{lemma:projective-adjacent-comparison}.

\label{lemma:kahler-two-time-shift}
With notation as above, for every $0\leq i\leq d$ and $0\leq m\leq\ell\leq N$,
\begin{equation}\label{eq:kahler-two-time-shift}
\int_{Y_N}\omega_{m,N}^{d-i}\wedge\omega_{\ell,N}^i=\lambda_d(f)^m\deg_i(f^{\ell-m}).
\end{equation}

\label{lemma:kahler-adjacent-comparison}
With notation as above, there is a constant $K_{f,\omega}\geq1$ such that for every $N\geq1$ and $0\leq m<N$,
\begin{equation}\label{eq:kahler-adjacent-comparison}
K_{f,\omega}^{-1}\,\omega_{m,N}\preceq_{Y_N}\omega_{m+1,N}\preceq_{Y_N}K_{f,\omega}\,\omega_{m,N}.
\end{equation}

\label{prop:kahler-log-laplacian}
Assume that \cref{setting:kahler} holds.
For every $1\leq i\leq d-1$ and $n\geq1$,
\begin{equation}\label{eq:kahler-log-laplacian}
\left|\log\frac{\deg_i(f^n)^2}{\deg_i(f^{n-1})\deg_i(f^{n+1})}\right|
\leq C'_{f,\omega,i}\,\frac{\sqrt{\deg_{i-1}(f^n)\deg_{i+1}(f^n)}}{\deg_i(f^n)},
\end{equation}
where $C'_{f,\omega,i}=2i(d-i)K_{f,\omega}^{2d+4}$ and $K_{f,\omega}$ is the constant in \cref{lemma:kahler-adjacent-comparison}.

\label{rmk:C-f-omega-i-limits}
By \cref{lemma:discrete-integration}, the leading constant also satisfies
\[
C_{f,\omega,i}=\lim_{n\to\infty}\frac{\deg_i(f^n)}{\lambda_i(f)^n}
=\lim_{n\to\infty}\frac{\deg_i(f^n)^{n+1}}{\deg_i(f^{n+1})^n}.
\]

\label{lemma:two-variable-maximum-principle}
Fix two integers $r<s$.
For each $r\leq i\leq s$, let $(u_{i,n})_{n\geq0}$ be a real sequence satisfying the following properties.
\begin{enumerate}[label=\textnormal{(\roman*)}]
\item \label{lemma:two-variable-maximum-principle-infinitesimal}
For every $r\le i\le s$,
\begin{equation}\label{eq:affine-interval-root-limit}
\lim_{n\to\infty} \frac{u_{i,n}}{n}=0.
\end{equation}

\item \label{lemma:two-variable-maximum-principle-temporal-estimate}
There exists $C_0>0$ such that for every $r<j<s$ and $n\geq1$,
\begin{equation}\label{eq:affine-interval-temporal-estimate}
\bigl|(\Delta_{\mathrm{tm}} u)_{j,n}\bigr|\leq
C_0\exp\Bigl(-\frac{1}{2}(\Delta_{\mathrm{sp}} u)_{j,n}\Bigr).
\end{equation}

\item \label{lemma:two-variable-maximum-principle-bounded}
There exists $C_1>0$ such that for every $n\geq0$,
\begin{equation}\label{eq:affine-interval-bounded}
\max\{u_{r,n},u_{s,n}\}\leq C_1.
\end{equation}
\end{enumerate}
Then there is a constant $C'_{u,r,s}>0$ such that for every $r\leq i\leq s$ and $n\geq1$,
\begin{equation}\label{eq:affine-interval-conclusion}
u_{i,n}\leq C'_{u,r,s}+2(i-r)(s-i)\log n.
\end{equation}

We \emph{expect} that a more delicate analysis of mixed intersections could improve the upper bound to $\operatorname{vol}(\Gamma_{[n]})=O\bigl(n^{\ell^2}\Lambda(f)^n\bigr)$.
Since $\lambda_1(f)=1$ implies $\ell=d$, whereas $\lambda_1(f)>1$ implies $\ell\leq d-1$, this would yield
\begin{equation}
\operatorname{vol}(\Gamma_{[n]})=
\begin{cases}
O\bigl(n^{d^2}\bigr), & \lambda_1(f)=1,\\
O\bigl(n^{(d-1)^2}\Lambda(f)^n\bigr), & \lambda_1(f)>1.
\end{cases}
\end{equation}
Note that when $f$ is a zero-entropy automorphism, the upper bound $\operatorname{vol}(\Gamma_{[n]})=O\bigl(n^{d^2}\bigr)$ is already known \cite[Corollary~1.2]{HJ25}.

\label{claim:degrees-matrix-norm}
For any $M\in \operatorname{M}_d(\mathbf{Z})$ with nonzero determinant, the induced isogeny $f_M$ of $E^d$ satisfies that for every $0\le j\le d$,
\begin{equation}\label{eq:abelian-matrix-degree}
\deg_{j,\Theta}(f_M^n)=j!(d-j)!\left\|\bigwedge\nolimits^jM^n\right\|_{\mathrm{F}}^2,
\end{equation}
where $\|\cdot\|_{\mathrm{F}}$ denotes the Frobenius norm of matrices.
In particular,
\[
\lambda_j(f_M)=\rho\Bigl(\bigwedge\nolimits^jM\Bigr)^2.
\]

\label{lemma:endpoint-criterion}
Under the hypotheses of \cref{thm:strict-break-asymptotics}, suppose in addition that
\begin{equation}\label{eq:adjacent-growth-condition}
\sqrt{\deg_{i-1,\omega}(f^n)\deg_{i+1,\omega}(f^n)}=O\bigl(s_i(f)^n\bigr).
\end{equation}
Then
\[
\deg_{i,\omega}(f^n)=C_{f,\omega,i}\,\lambda_i(f)^n+O\bigl(s_i(f)^n\bigr).
\]

\label{question:polynomial-dyn-deg}
Assume that either \cref{setting:projective} or \cref{setting:kahler} holds, and let $1\leq i\leq d-1$.

\begin{enumerate}[label=\textnormal{(\arabic*)}]
\item \emph{Existence.}
Does the limit
\[
\mu_i(f)\coloneqq\lim_{n\to\infty}\frac{\log\deg_{i,\omega}(f^n)-n\log\lambda_i(f)}{\log n}
\]
exist?

\item \emph{Two-sided growth.}
If the limit exists, does one have
\[
\deg_{i,\omega}(f^n)\asymp n^{\mu_i(f)}\lambda_i(f)^n?
\]

\item \emph{Integrality.}
If the limit exists, is $\mu_i(f)\in\mathbf{Z}_{\geq0}$?
\end{enumerate}
